WITH with_latest AS (SELECT s.id, s.balance, s.opened_date, x.txn_type FROM accounts s LEFT JOIN LATERAL (SELECT c.txn_type FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, opened_date, txn_type, CASE WHEN txn_type RLIKE '^(CREDIT|DEBIT)$' THEN 'PRIORITY' WHEN txn_type RLIKE '^(REFUND|FEE)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS txn_type_zone FROM with_latest;
